def load() -> bytes:
    """解出 524,350 字节的标准 PC-98 2048x2048 1-bit 字库位图。"""
    blob = zlib.decompress(base64.b64decode(_PAYLOAD))
    hdr, mask, cells = blob[:62], blob[62:2110], memoryview(blob[2110:])
    pix = bytearray(b"\xff" * 524288)
    pos = 0
    for idx in range(16384):
        if mask[idx >> 3] & (1 << (idx & 7)):
            cx, cy = idx & 127, idx >> 7
            c = cells[pos : pos + 32]
            pos += 32
            for dy in range(16):
                off = (2047 - (cy * 16 + dy)) * 256 + cx * 2
                pix[off : off + 2] = c[dy * 2 : dy * 2 + 2]
    return hdr + bytes(pix)
